import { SOUND_PACKS,MUSIC_STYLES } from './synthesis.js';
import { readSettings,writeSettings } from './settings.js';
let preferences=readSettings();
function cards(items,kind,key){return items.map(item=>`<article class="lab-card ${preferences[key]===item.id?'selected':''}" data-card="${item.id}"><small>${item.badge}</small><h3>${item.name}</h3><p>${item.description}</p><audio controls preload="none" aria-label="试听${item.name}" src="audio/previews/${kind}-${item.id}.wav"></audio><button data-select="${item.id}" data-key="${key}" aria-pressed="${preferences[key]===item.id}">${preferences[key]===item.id?'✓ 当前选择':'应用这套'+(kind==='sfx'?'音效':'音乐')}</button></article>`).join('');}
function render(){document.querySelector('#sfxChoices').innerHTML=cards(SOUND_PACKS,'sfx','soundPack');document.querySelector('#musicChoices').innerHTML=cards(MUSIC_STYLES,'music','musicStyle');update();document.querySelectorAll('audio').forEach(a=>{a.volume=.65;a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(other=>{if(other!==a)other.pause();}));});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{preferences={...preferences,[b.dataset.key]:b.dataset.select,muted:false};const ok=writeSettings(preferences);update();const toast=document.querySelector('#toast');toast.textContent=ok?'已应用。回到游戏就能听见；总音量沿用你的设置。':'浏览器无法保存设置，请在游戏内重新选择。';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3200);});}
function update(){document.querySelector('#currentChoice').textContent=`当前组合：${SOUND_PACKS.find(x=>x.id===preferences.soundPack).name} ＋ ${MUSIC_STYLES.find(x=>x.id===preferences.musicStyle).name}`;document.querySelectorAll('[data-select]').forEach(b=>{const selected=preferences[b.dataset.key]===b.dataset.select;b.textContent=selected?'✓ 当前选择':'应用这套'+(b.dataset.key==='soundPack'?'音效':'音乐');b.setAttribute('aria-pressed',String(selected));b.closest('.lab-card').classList.toggle('selected',selected);});}
render();document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('audio').forEach(a=>a.pause());});
